// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, optionFigures, steps, context, audio, numericAnswer} = row;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(figure || optionFigures ? {choiceLayout: {condition: figure, options},
        choiceImages: options.map(option => option.image),
        ...(figure ? {conditionImage: figure.src, conditionAlt: figure.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"golden-fleece","year":2008,"grade":"2-4","contest":"Золотое руно","letters":"DN?","count":90,"language":"ru","points":3,"tasksFile":"tasks-2-4.pdf","answersFile":"reviewed-2-4.pdf","sections":[{"start":1,"title":"1861–1870"},{"start":19,"title":"1871–1880"},{"start":37,"title":"1881–1890"},{"start":55,"title":"1891–1900"},{"start":73,"title":"1901–1914"}],"reviewedKey":true}, [{"question":"Объединение Италии.","context":"1861–1870. Изменение карты европы","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Объединение Италии","steps":["В 1861 году было провозглашено Итальянское королевство во главе с Виктором Эммануилом II. Объединение продолжилось присоединением Венеции в 1866 году.","В 1870 году итальянские войска вошли в Рим. Эти основные события укладываются в период 1861–1870 годов."]},{"question":"Германскую империю провозгласили в Версале в 1870 году.","context":"1861–1870. Изменение карты европы","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Объединение Германии","steps":["Договоры об объединении ряда немецких государств заключили в 1870 году. Затем в Версале провели отдельную церемонию провозглашения империи.","Церемония состоялась 18 января 1871 года. В утверждении указан предыдущий год."],"reviewedEdition":true},{"question":"Преобразование Австрийской империи в Австро-Венгрию.","context":"1861–1870. Изменение карты европы","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Австрийская империя","steps":["В 1867 году Австрийская империя заключила соглашение с венгерскими политиками. Венгрия получила собственные органы власти.","Так возникла Австро-Венгрия, объединённая монархией. 1867 год входит в указанный период."]},{"question":"Отмена крепостного права.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Крепостное право","steps":["Император Александр II подписал документы крестьянской реформы в феврале 1861 года по старому стилю. Миллионы крепостных получили личную свободу.","1861 год — начало указанного отрезка. Утверждение верно."]},{"question":"Россия продает США остров Сахалин.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Сделка с США","steps":["В 1867 году Российская империя уступила США свои владения на северо-западе Америки. Эти земли включали Аляску и Алеутские острова.","Сахалин находится у восточного берега Азии и не входил в эту сделку."]},{"question":"Россия продает Великобритании Аляску.","context":"1861–1870. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кому досталась Аляска","steps":["Соглашение о передаче Аляски подписали в 1867 году представители Российской империи и США. Новые власти приняли её в том же году.","Покупателем были Соединённые Штаты. Великобритания в сделке не участвовала."]},{"question":"Гражданская война в США продолжалась с 1861 по 1865 год.","context":"1861–1870. Гражданская война в сша","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Даты Гражданской войны","steps":["В апреле 1861 года начались боевые действия между Союзом северных штатов и Конфедерацией.","Капитуляция армии Роберта Ли и другие завершающие события относятся к 1865 году. Обе даты указаны верно."],"reviewedEdition":true},{"question":"Второе название войны – Война Севера и Юга.","context":"1861–1870. Гражданская война в сша","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Название войны в США","steps":["Союз северных штатов воевал с Конфедерацией, созданной южными штатами. Такое деление сторон запомнилось в названиях войны.","Поэтому её называют Гражданской войной в США или войной Севера и Юга."]},{"question":"Войсками Конфедеративных штатов руководил Дж. Вашингтон.","context":"1861–1870. Гражданская война в сша","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Командующий конфедератов","steps":["Джордж Вашингтон возглавлял американские войска ещё в войне за независимость XVIII века. К началу Гражданской войны его уже давно не было в живых.","Один из главных военачальников Конфедерации — Роберт Ли. В задании указан другой человек."]},{"question":"1862 год.","context":"1861–1870. Памятники русской истории. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Год открытия памятника","figure":{"src":"assets/golden-fleece/2008/2008_24_I-10.jpg","alt":"На каменном постаменте несколько ярусов фигур, наверху фигуры у державы.","width":307,"height":437},"steps":["На снимке многоярусный памятник с фигурами и державой вверху. Это «Тысячелетие России» в Великом Новгороде.","Памятник открыли в 1862 году. Указанная дата соответствует истории памятника."]},{"question":"1864 год.","context":"1861–1870. Памятники русской истории. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Две фигуры на постаменте","figure":{"src":"assets/golden-fleece/2008/2008_24_I-11.jpg","alt":"Две бронзовые фигуры на высоком постаменте, одна стоит, другая сидит.","width":307,"height":437},"steps":["Один из героев стоит и поднимает руку, а другой сидит, опираясь на щит. Так выглядят Минин и Пожарский в скульптурной композиции Ивана Мартоса.","Московский памятник открыли в 1818 году, намного раньше указанного 1864-го."]},{"question":"1867 год.","context":"1861–1870. Памятники русской истории. определите, верно ли указаны годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Всадник на скале","figure":{"src":"assets/golden-fleece/2008/2008_24_I-12.jpg","alt":"Бронзовый всадник на вздыбленном коне на массивной скале.","width":331,"height":437},"steps":["Конь поднялся на дыбы, а основание выглядит как большой необработанный камень. Это памятник Петру I «Медный всадник».","Памятник открыли в Санкт-Петербурге в 1782 году. Подпись «1867 год» неверна."]},{"question":"Члены кружка «Могучая кучка» были русскими композиторами.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Участники кружка","steps":["В «Могучую кучку» входили Балакирев, Бородин, Кюи, Мусоргский и Римский-Корсаков. Их связывал интерес к русской народной песне и истории.","Все пятеро известны как русские композиторы. Утверждение соответствует составу кружка."]},{"question":"Руководителем «Могучей кучки» был М. Глинка.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Руководитель композиторов","steps":["Кружок вырос из встреч композиторов вокруг Милия Балакирева. Он обсуждал с товарищами их сочинения и знакомил их с музыкой предшественников.","Михаил Глинка повлиял на их взгляды, но умер в 1857 году и кружком не руководил."]},{"question":"Оркестровое произведение Балакирева «1000 лет», связанное с юбилеем России, появилось в 1860-х годах.","context":"1861–1870. Появление музыкального объединения «могучая кучка»","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Увертюра и памятник","steps":["Симфоническая картина «1000 лет» посвящена истории страны. Балакирев работал над ней в первой половине 1860-х годов.","Ранняя редакция относится к 1863–1864 годам. Название «Русь» Балакирев дал более поздней переработке произведения."],"reviewedEdition":true},{"question":"Д. Менделеев составляет свою знаменитую таблицу.","context":"1861–1870. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Таблица элементов","steps":["Дмитрий Менделеев сравнил свойства известных химических элементов и заметил периодическое повторение этих свойств.","Первый вариант своей таблицы он составил в 1869 году. Этот год входит в заданный период."]},{"question":"А. Нобель изобретает динамит.","context":"1861–1870. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Изобретение Нобеля","steps":["Опасную жидкость нитроглицерин Альфред Нобель соединял с пористым материалом, чтобы получить более устойчивый состав. Изобретение получило название «динамит».","Патент на динамит относится к 1867 году. Указанный отрезок времени подходит."]},{"question":"Братья Монгольфье проводят первый публичный сеанс кино.","context":"1861–1870. Достижения в науке и технике","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Изобретатели и кино","steps":["Братья Монгольфье известны демонстрациями воздушного шара в 1783 году. Киноаппаратура появилась более чем столетие спустя.","Один из самых известных ранних публичных киносеансов устроили братья Люмьер в 1895 году. Имена и время в условии не подходят."]},{"question":"Россия вступает в войну с Турцией.","context":"1871–1880. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Война России с Турцией","steps":["В апреле 1877 года Российская империя объявила войну Османской империи. Итоги войны обсуждались на международных переговорах в 1878 году.","Обе даты входят в период 1871–1880 годов. Утверждение верно."]},{"question":"Венеция становится столицей Италии.","context":"1871–1880. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Итальянская столица","steps":["Итальянское королевство сначала управлялось из Турина, затем из Флоренции. После присоединения Рима туда перенесли столицу.","Рим официально стал столицей в 1871 году. Венеция ею не была."]},{"question":"Падение Парижской коммуны.","context":"1871–1880. События в европе","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Конец Парижской коммуны","steps":["Весной 1871 года в Париже действовала Коммуна. В мае войска правительства взяли город.","Коммуна прекратила существование к концу мая 1871 года. Это начало указанного периода."]},{"question":"А. Островский создает пьесу «Снегурочка».","context":"1871–1880. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Пьеса о Снегурочке","steps":["В «Весенней сказке» действуют Снегурочка, Лель и царь Берендей. Автор пьесы также написал «Грозу».","Пьесу «Снегурочка» сочинил Александр Островский в 1873 году. И автор, и период указаны верно."]},{"question":"Р. Стивенсон пишет роман «Пятнадцатилетний капитан».","context":"1871–1880. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Автор романа о капитане","steps":["Роман о юном Дике Сэнде, который берёт на себя командование кораблём, вышел в 1878 году. Он входит в серию приключенческих романов Жюля Верна.","Роберт Стивенсон написал, например, «Остров сокровищ». «Пятнадцатилетний капитан» принадлежит Верну."]},{"question":"Ж. Верн завершает роман «Вокруг света за 80 дней».","context":"1871–1880. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Роман о кругосветном пути","steps":["Филеас Фогг заключает пари и должен объехать земной шар за 80 дней. История сначала выходила частями в газете.","Жюль Верн завершил публикацию в 1872 году, а книга вышла в 1873-м. Обе даты внутри заданного периода."]},{"question":"Завершение строительства Статуи Свободы в Вашингтоне.","context":"1871–1880. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Город Статуи Свободы","steps":["Франция подарила США статую женщины с факелом. Её возвели на острове у входа в нью-йоркскую гавань.","Открытие состоялось в 1886 году. Условие ошибается и в городе, и в периоде."]},{"question":"В 1880 году состоялось торжественное открытие Кельнского собора.","context":"1871–1880. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Торжество в Кёльне","steps":["Строительство Кёльнского собора началось ещё в Средние века и надолго прервалось. В XIX веке его достроили по историческому проекту.","Торжества по случаю завершения строительства состоялись в 1880 году. В этом смысле указанная дата верна."]},{"question":"Начинается строительство церкви Сакре-Кёр в Париже.","context":"1871–1880. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало строительства церкви","steps":["Базилику Сакре-Кёр построили на парижском холме Монмартр. Первый камень заложили в 1875 году.","Это относится к периоду 1871–1880 годов. Освятили базилику намного позднее."]},{"question":"Картина называется «После побоища Игоря Святославича с половцами».","context":"1871–1880. Картины в. васнецова. определите, правильно ли указаны их названия","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Название картины о битве","figure":{"src":"assets/golden-fleece/2008/2008_24_I-28.jpg","alt":"Поле после битвы, на земле лежат воины, над ними летят птицы.","width":484,"height":295},"steps":["Виктор Васнецов изобразил поле после битвы из «Слова о полку Игореве». На картине воины лежат среди травы, а над ними летят птицы.","Третьяковская галерея приводит название «После побоища Игоря Святославича с половцами» и датирует картину 1880 годом."],"reviewedEdition":true},{"question":"Художник назвал показанную картину «Ковёр-самолёт».","context":"Проверь, правильно ли указано название картины.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Сказочный полёт","figure":{"src":"assets/golden-fleece/2008/2008_24_I-29.jpg","alt":"На узорчатом ковре над рекой и лесом стоит один человек. Рядом с ним светится клетка.","width":496,"height":295},"steps":["На ковре над землёй летит Иван-царевич. Вместе с ним видна ярко освещённая клетка с Жар-птицей.","Виктор Васнецов написал это полотно в 1880 году и назвал его «Ковёр-самолёт». Значит, утверждение верно."],"reviewedEdition":true},{"question":"Эта картина Виктора Васнецова называется «Витязь на распутье».","context":"Проверь, правильно ли указано название картины.","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Всадник и вещий камень","figure":{"src":"assets/golden-fleece/2008/2008_24_I-30.jpg","alt":"Воин на светлом коне смотрит на камень среди поля.","width":472,"height":283},"steps":["Богатырь остановил коня перед камнем с надписью. Ему нужно выбрать дальнейший путь.","Русский музей называет полотно «Витязь на распутье». Первый вариант Васнецов показал в 1878 году, окончательный создал в 1882-м."],"reviewedEdition":true},{"question":"В 1874 году М. Мусоргский, находясь под впечатлением от выставки художника В. Гартмана, пишет фортепианную сюиту «Картинки с выставки».","context":"1871–1880. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Музыка после выставки","steps":["После смерти художника Виктора Гартмана устроили выставку его работ. Композитор увидел там эскизы, которые подсказали ему сюжеты музыкальных пьес.","Модест Мусоргский написал «Картинки с выставки» для фортепиано в 1874 году. Утверждение верно."]},{"question":"Н. Римский-Корсаков создает балет «Лебединое озеро».","context":"1871–1880. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Композитор «Лебединого озера»","steps":["Балет на сюжет о девушке-лебеде впервые показали в Москве в 1877 году. Он входит в один ряд со «Спящей красавицей» и «Щелкунчиком».","Музыку написал Пётр Чайковский. В условии названа фамилия другого композитора."]},{"question":"П. Чайковский заканчивает оперу «Князь Игорь».","context":"1871–1880. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Автор «Князя Игоря»","steps":["Основой оперы стало «Слово о полку Игореве». Александр Бородин работал над партитурой много лет и оставил её неоконченной.","После смерти Бородина работу над оперой продолжили Римский-Корсаков и Глазунов. Чайковский её не заканчивал."]},{"question":"А. Белл изобретает телефон.","context":"1871–1880. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Телефон и патент","steps":["Александр Грэм Белл получил патент США на устройство для передачи звука по электрическому проводу в 1876 году.","Этот год входит в указанный период. Над подобными устройствами одновременно работали и другие изобретатели."]},{"question":"Стационарный двухтактный двигатель, разработанный Карлом Бенцем, впервые заработал в 1879 году.","context":"1871–1880. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Двигатель Карла Бенца","steps":["Карл Бенц сначала работал над стационарным двигателем. Такой двигатель предназначался для работы на одном месте.","Первое испытание состоялось в конце 1879 года. Автомобиль с двигателем Бенц разработал в следующем десятилетии."],"reviewedEdition":true},{"question":"В 1879 году компания Сименса показала в Берлине электрическую железную дорогу с питанием от рельса.","context":"1871–1880. Технические изобретения","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первый электролокомотив","steps":["На берлинской выставке демонстрировали поезд, который перевозил посетителей по небольшому кольцу. Электричество поступало к локомотиву через рельс.","Поезд компании Сименса показали в 1879 году. Дата и способ питания в утверждении верны."],"reviewedEdition":true},{"question":"Президент США А. Линкольн смертельно ранен во время спектакля в Вашингтоне.","context":"1881–1890. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Покушение в театре","steps":["Авраама Линкольна смертельно ранили в театре Форда в Вашингтоне. Это случилось в апреле 1865 года в конце Гражданской войны.","Место в утверждении верно, но событие не относится к 1881–1890 годам."]},{"question":"Начинается правление последнего императора Германии – Вильгельма II .","context":"1881–1890. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало правления Вильгельма","steps":["Вильгельм II стал германским императором в 1888 году. В один год на престоле сменились три императора.","Он оставался императором до конца Первой мировой войны и стал последним правителем с этим титулом. Дата в периоде верна."]},{"question":"Во Франции свергнут последний император – Наполеон II .","context":"1881–1890. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Последний император Франции","steps":["Последним французским императором был Наполеон III. Его лишили власти после поражения под Седаном в 1870 году.","В утверждении указан Наполеон II, к тому же 1870 год лежит вне периода 1881–1890."]},{"question":"Убийство 1 марта 1881 года императора Александра I .","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Император и дата","steps":["1 марта 1881 года по старому стилю в Петербурге смертельно ранили Александра II. Место покушения позднее отметили строительством храма.","Александр I умер в 1825 году. В утверждении перепутаны два императора."]},{"question":"После смерти Александра I новым императором России становится Николай II .","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Наследование престола","steps":["После смерти Александра I в 1825 году престол занял Николай I. Карьера Николая II относится уже к концу XIX века.","Николай II вступил на престол в 1894 году после смерти своего отца Александра III."]},{"question":"Начинается Крымская война, в которой участвуют Россия, Англия, Франция и Германия.","context":"1881–1890. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Крымская война и даты","steps":["Крымская война шла в 1853–1856 годах. Великобритания и Франция выступили против России на стороне Османской империи.","В период 1881–1890 она не попадает. Германской империи в годы Крымской войны ещё не существовало."]},{"question":"Э. Дега. «Пьеро и Арлекин».","context":"1881–1890. Шедевры мировой живописи. определите, верны ли авторы и названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Цветы в вазе","figure":{"src":"assets/golden-fleece/2008/2008_24_I-43.jpg","alt":"Ваза с жёлтыми цветами на однотонном жёлтом фоне.","width":295,"height":366},"steps":["На репродукции жёлтые цветы с круглыми сердцевинами стоят в вазе. Это один из вариантов «Подсолнухов».","Серию написал Винсент ван Гог. Сюжет и автор в подписи не соответствуют картине."]},{"question":"В. ван Гог. «Подсолнухи».","context":"1881–1890. Шедевры мировой живописи. определите, верны ли авторы и названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Два карнавальных костюма","figure":{"src":"assets/golden-fleece/2008/2008_24_I-44.jpg","alt":"Два человека в белом и красном клетчатом карнавальных костюмах.","width":295,"height":366},"steps":["На картине две фигуры. Одна в белом костюме Пьеро, другая в красном с ромбами, как Арлекин.","Это «Пьеро и Арлекин» Поля Сезанна. Подсолнухи ван Гога изображены в соседней задаче."]},{"question":"И. Левитан. «Боярыня Морозова».","context":"1881–1890. Шедевры мировой живописи. определите, верны ли авторы и названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фигура на санях","figure":{"src":"assets/golden-fleece/2008/2008_24_I-45.jpg","alt":"В центре снежной улицы сани, на них женщина в чёрном с поднятой рукой.","width":307,"height":366},"steps":["На репродукции женщина поднимает руку в двуперстии. Её везут по снегу в санях среди толпы.","Это картина Василия Сурикова «Боярыня Морозова». Название в условии верно, художник назван неверно."]},{"question":"В Париже воздвигается Эйфелева башня.","context":"1881–1890. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Башня для выставки","steps":["Эйфелеву башню возвели для Всемирной выставки. Строительные работы начались в 1887 году и завершились в 1889-м.","Обе даты входят в отрезок 1881–1890 годов. Событие действительно произошло в Париже."]},{"question":"На месте убийства Александра I начинается строительство храма «Спас-на-крови».","context":"1881–1890. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Храм на месте покушения","steps":["В Санкт-Петербурге строительство храма Спаса на Крови началось в 1883 году. Участок выбран в память о гибели императора от покушения.","Здесь был смертельно ранен Александр II. Период подходит, но имя в условии неверно."]},{"question":"Строительство храма Святого Семейства в Барселоне началось в 1882 году.","context":"1881–1890. Памятники эпохи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Начало Саграда-Фамилия","steps":["Первый камень храма, известного как Саграда-Фамилия, заложили в 1882 году. Антони Гауди присоединился к проекту в следующем году.","1882 год относится к указанному периоду. Храм Святого Семейства сегодня имеет статус базилики."],"reviewedEdition":true},{"question":"В 1888 году Н. Римский-Корсаков, находясь под впечатлением от арабских сказок «Тысяча и одна ночь», пишет симфоническую сюиту «Шехеразада».","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Сказки в симфонии","steps":["В оркестровой сюите звучат темы, навеянные историями из «Тысячи и одной ночи». Название напоминает о рассказчице Шехеразаде.","Сюиту «Шехеразада» Римский-Корсаков написал в 1888 году. Атрибуция и дата верны."]},{"question":"Николай Римский-Корсаков завершил оркестровку оперы «Снегурочка» в 1881 году.","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Время создания оперы","steps":["Композитор подготовил набросок оперы летом 1880 года. Затем он распределил партии между инструментами оркестра.","В воспоминаниях Римский-Корсаков указал, что завершил оркестровку в марте 1881 года."],"reviewedEdition":true},{"question":"В 1889 году А. Рубинштейн пишет балет «Спящая красавица».","context":"1881–1890. Музыкальная жизнь","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Музыка «Спящей красавицы»","steps":["В 1889 году была закончена музыка балета «Спящая красавица». Его премьера прошла в Петербурге в начале 1890 года.","Композитор — Пётр Чайковский. Антон Рубинштейн музыку этого балета не писал."]},{"question":"Н. Пржевальский достигает Южного полюса.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Маршруты Пржевальского","steps":["Пржевальский исследовал Центральную Азию, включая районы Монголии, Китая и Тибета. Его экспедиции проходили в Северном полушарии.","Южный полюс находится в Антарктиде. Экспедиции Пржевальского туда не направлялись."]},{"question":"Ф. Нансен пересекает на лыжах остров Гренландия.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Путь через Гренландию","steps":["Норвежский исследователь Фритьоф Нансен и его спутники пересекли ледниковый щит Гренландии на лыжах. Они прошли с восточного берега на западный.","Поход состоялся в 1888 году. Эта дата входит в указанный отрезок."]},{"question":"Р. Амундсен и Р. Скотт совершают экспедицию на Северный полюс.","context":"1881–1890. Великие путешественники","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Какой полюс","steps":["Амундсен и Скотт известны соперничеством в исследованиях Антарктиды. Экспедиция Амундсена достигла Южного полюса в декабре 1911 года, группа Скотта прибыла в январе 1912-го.","Речь о Южном полюсе и более позднем периоде. Утверждение неверно по двум признакам."]},{"question":"В 1898 году на Аляске около Нома нашли золото.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Золотая лихорадка","steps":["Ном находится на западном побережье Аляски. Рядом с ним золото обнаружили в 1898 году, и вскоре туда приехали старатели.","Событие произошло в указанный период. Отдельная золотая лихорадка в Клондайке началась в 1896 году на территории канадского Юкона."],"reviewedEdition":true},{"question":"Начинается строительство Суэцкого канала.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Суэцкий канал","steps":["Канал между Средиземным и Красным морями строили с 1859 года. Первые суда прошли по нему после открытия в 1869-м.","Строительство началось раньше периода 1891–1900. Утверждение о времени неверно."]},{"question":"Завершается строительство Панамского канала.","context":"1891–1900. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Даты Панамского канала","steps":["Французская компания начала работы на Панамском перешейке в 1881 году. После перерыва строительство продолжили под руководством США.","Канал официально открыли в 1914 году. В 1891–1900 годах работы не завершились."]},{"question":"Открытие Русского музея в Санкт-Петербурге.","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Открытие Русского музея","steps":["Русский музей создавали как собрание произведений отечественного искусства. Для него отвели Михайловский дворец в Санкт-Петербурге.","Музей торжественно открыли в 1898 году. Город и период указаны верно."]},{"question":"Открытие в Москве Музея изящных искусств имени Александра III .","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Московский музей искусства","steps":["Музей имени императора Александра III строили как общедоступное собрание по истории искусства. Сейчас это ГМИИ имени Пушкина.","Музей открылся в Москве в 1912 году. Отрезок 1891–1900 для открытия не подходит."]},{"question":"Открытие в Санкт-Петербурге Третьяковской галереи.","context":"1891–1900. Художественные объединения и музеи","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Город коллекции Третьякова","steps":["Павел Третьяков передал своё собрание и коллекцию брата городу в 1892 году. Городскую галерею открыли для посетителей в 1893-м.","Она появилась в Москве. Петербург из условия не соответствует истории галереи."]},{"question":"«Переход Суворова через Альпы».","context":"1891–1900. Исторические полотна. определите, правильно ли указаны названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Бой на реке","figure":{"src":"assets/golden-fleece/2008/2008_24_I-61.jpg","alt":"Много людей в лодках у высокого речного берега, над водой клубы дыма.","width":461,"height":272},"steps":["На картине много лодок и людей у берега. Это сцена похода казаков под руководством Ермака.","Полотно Сурикова называется «Покорение Сибири Ермаком». Альпийские горы изображены в другой его картине."]},{"question":"«Запорожцы пишут письмо турецкому султану».","context":"1891–1900. Исторические полотна. определите, правильно ли указаны названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Письмо султану","figure":{"src":"assets/golden-fleece/2008/2008_24_I-62.jpg","alt":"Толпа людей в казачьей одежде окружает писаря у стола.","width":461,"height":272},"steps":["Люди собрались вокруг писаря, который ведёт запись. У многих участников сцены весёлые лица и выразительные жесты.","Картина Ильи Репина называется «Запорожцы», её также знают как «Запорожцы пишут письмо турецкому султану». Подпись верна."]},{"question":"«Покорение Сибири Ермаком».","context":"1891–1900. Исторические полотна. определите, правильно ли указаны названия фрагментов картин","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Люди на снежном склоне","figure":{"src":"assets/golden-fleece/2008/2008_24_I-63.jpg","alt":"Военные спускаются по крутому снежному склону в горах.","width":449,"height":272},"steps":["Перед нами горный склон, по которому спускаются солдаты. Это эпизод перехода армии Суворова через Альпы.","Так называется и полотно Сурикова. Название о походе Ермака относится к другой сцене."]},{"question":"Ч. Диккенс пишет «Приключения Тома Сойера».","context":"1891–1900. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Автор истории о Томе","steps":["Том Сойер живёт в американском городке у реки Миссисипи. Его приключения связаны с американским писателем, который сам вырос на этой реке.","Автор — Марк Твен. Роман вышел в 1876 году, а Диккенс умер в 1870-м."]},{"question":"В 1894-95 годах английский писатель Р. Киплинг публикует «Книгу джунглей».","context":"1891–1900. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Книги о джунглях","steps":["Первая «Книга джунглей» Редьярда Киплинга вышла в 1894 году. Спустя год появилась «Вторая книга джунглей».","Оба издания попадают в период 1891–1900 годов. Маугли появляется в историях Киплинга о джунглях."]},{"question":"В 1894 году английский писатель Л. Кэрролл создает персонажей своих сказок: Маугли и Рикки-Тикки-Тави.","context":"1891–1900. Мировая литература","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Герои двух сказочников","steps":["Маугли и мангуст Рикки-Тикки-Тави — персонажи произведений Киплинга. В этих рассказах действие связано с Индией и джунглями.","Льюис Кэрролл создал другой сказочный мир, где путешествует Алиса. Авторы перепутаны."]},{"question":"П. Чайковский пишет оперу «Мазепа» по одноименной поэме А. Пушкина.","context":"1891–1900. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Литературная основа «Мазепы»","steps":["Опера Чайковского «Мазепа» основана на сюжете пушкинской поэмы «Полтава». У поэмы и оперы разные названия.","Композитор закончил оперу в 1883 году. Это раньше указанного периода 1891–1900."]},{"question":"С. Прокофьев в возрасте 5 лет создает свое первое произведение «Индийский галоп».","context":"1891–1900. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая пьеса композитора","steps":["Сергей Прокофьев родился в 1891 году. Уже в детстве он начал придумывать музыку и записывать её с помощью матери.","Одну из первых пьес, «Индийский галоп», он сочинил в пять лет. Это произошло в 1890-х годах."]},{"question":"А. Скрябин пишет оперу «Сказка о царе Салтане».","context":"1891–1900. Русская музыка","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Кто написал сказочную оперу","steps":["Гвидон, царевна Лебедь и царь Салтан действуют в опере по сказке Пушкина. Её композитор известен и другими операми на сказочные темы.","Музыка принадлежит Николаю Римскому-Корсакову. Александр Скрябин не писал эту оперу."]},{"question":"П. Кюри и М. Кюри изобретают метод сохранения продуктов путем пастеризации.","context":"1891–1900. Достижения в науке","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Имена и пастеризация","steps":["Пастеризация получила название от фамилии Луи Пастера. Он исследовал, как нагрев помогает уничтожить часть микроорганизмов в продуктах.","Пьер и Мария Кюри изучали радиоактивность. Пастеризация с их исследованиями не связана."]},{"question":"Л. Пастер открывает радиоактивное излучение.","context":"1891–1900. Достижения в науке","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Открытие радиоактивности","steps":["В 1896 году Анри Беккерель заметил, что соединения урана засвечивают фотопластинки без предварительного освещения. Так было открыто естественное радиоактивное излучение.","Луи Пастер известен работами по микробиологии. Утверждение ошибается в имени учёного."]},{"question":"В. Рентген открывает Х-лучи, способные проходить через различные материалы.","context":"1891–1900. Достижения в науке","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Открытие Х-лучей","steps":["Вильгельм Рентген заметил лучи при опытах с разрядной трубкой. Они могли проходить через некоторые непрозрачные материалы.","Это произошло в 1895 году. Х-лучи также называют рентгеновскими."]},{"question":"Первая Балканская война.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая Балканская война","steps":["Война Балканского союза с Османской империей началась в октябре 1912 года. Мир заключили в 1913-м.","Обе даты входят в период 1901–1914. Утверждение верно."]},{"question":"Создание Антанты – союза государств, в который вошли Россия, Англия и Франция.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Соглашения Антанты","steps":["В 1904 году Великобритания и Франция урегулировали ряд разногласий. В 1907 году Великобритания заключила соглашение и с Россией.","Эти события завершили складывание Тройственной Антанты в начале XX века. Страны в условии названы верно."]},{"question":"Русско-японская война.","context":"1901–1914. События в мире","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Время русско-японской войны","steps":["Русско-японская война началась в феврале 1904 года. Мирный договор подписали в 1905-м.","И начало, и конец войны относятся к периоду 1901–1914."]},{"question":"В 1905 году произошла первая русская революция.","context":"1901–1914. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первая русская революция","steps":["Массовые выступления начались в 1905 году. Революционные события и политические изменения продолжались ещё два года.","Поэтому первую русскую революцию обычно датируют 1905–1907 годами. Её начало попадает в отрезок из условия."]},{"question":"Толчком к революции стал расстрел демонстрации в Санкт-Петербурге 9 января 1905 года.","context":"1901–1914. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Январская демонстрация","steps":["В Петербурге рабочие шли с петицией к императору. Войска открыли огонь по демонстрантам. Это событие известно как Кровавое воскресенье.","По действовавшему тогда в России календарю это произошло 9 января 1905 года. Событие стало одним из толчков к революции."]},{"question":"Произведена первая перепись населения.","context":"1901–1914. События в россии","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Год первой переписи","steps":["Первая всеобщая перепись населения Российской империи проводилась в январе 1897 года по старому стилю.","Это было до начала отрезка 1901–1914 годов. Событие названо правильно, но время не подходит."]},{"question":"Русский флот побеждает в Цусимском сражении.","context":"1901–1914. Русско-японская война","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Итог морского сражения","steps":["Цусимское сражение произошло в мае 1905 года. Русская эскадра потеряла значительную часть кораблей.","Победу одержал японский флот. Утверждение о победе России неверно."]},{"question":"После боя у корейского порта Чемульпо в 1904 году экипаж затопил крейсер «Варяг».","context":"1901–1914. Русско-японская война","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Где затопили корабль","steps":["Во время русско-японской войны крейсер «Варяг» участвовал в бою у Чемульпо. После боя корабль вернулся в порт.","Экипаж затопил крейсер в Чемульпо в феврале 1904 года. Утверждение верно."],"reviewedEdition":true},{"question":"Россия одерживает победу в русско-японской войне.","context":"1901–1914. Русско-японская война","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Итог войны","steps":["В 1905 году Россия и Япония заключили Портсмутский мир. По договору Япония получила южную часть Сахалина и права на аренду Порт-Артура.","Исход войны не был победой России. В утверждении её итог указан неверно."]},{"question":"Нобелевские премии присуждаются начиная с 1901 года.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Первые Нобелевские премии","steps":["Альфред Нобель предусмотрел в завещании ежегодные награды за достижения в науке, литературе и деле мира.","Первые Нобелевские премии вручили в 1901 году. Эта дата верна."]},{"question":"И. Павлов – первый российский ученый, ставший лауреатом Нобелевской премии.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Премия русскому учёному","steps":["В 1904 году Нобелевскую премию по физиологии или медицине присудили за исследования пищеварения. Награждённый учёный работал в России.","Это Иван Павлов, первый российский лауреат Нобелевской премии. Илья Мечников получил её в 1908 году."]},{"question":"В 1907 году Р. Киплинг получает Нобелевскую премию по литературе.","context":"1901–1914. Нобелевские премии","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Премия Киплингу","steps":["Редьярд Киплинг написал «Книгу джунглей», рассказы и стихотворения. Шведская академия отметила его литературное творчество.","Нобелевскую премию по литературе ему присудили в 1907 году. Утверждение верно."]},{"question":"Четырёхмоторный самолёт Игоря Сикорского «Илья Муромец», оборудованный пассажирским салоном, впервые поднялся в воздух в 1913 году.","context":"1901–1914. Достижения в развитии транспорта","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Пассажирский самолёт","steps":["На самолёте установили четыре двигателя. Внутри корпуса предусмотрели помещения для пассажиров.","Первый полёт «Ильи Муромца» состоялся в декабре 1913 года. Указанная дата подходит."],"reviewedEdition":true},{"question":"Построен лайнер «Титаник» – самый большой корабль своего времени.","context":"1901–1914. Достижения в развитии транспорта","choices":["Верно","Неверно","Не знаю"],"answer":0,"title":"Крупнейший лайнер","steps":["Пассажирский лайнер «Титаник» построили в Белфасте. К моменту выхода в первый рейс в 1912 году он был крупнейшим судном по вместимости.","Даты строительства и завершения подходят к периоду 1901–1914. Утверждение верно."]},{"question":"Дирижабль «Граф Цеппелин» совершает первый пассажирский трансатлантический перелет.","context":"1901–1914. Достижения в развитии транспорта","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Перелёт через Атлантику","steps":["Дирижабль «Граф Цеппелин» начал полёты в конце 1920-х годов. Его известный перелёт с пассажирами через Атлантику состоялся в 1928-м.","Это позже периода 1901–1914 годов. Утверждение по дате не подходит."]},{"question":"1903 год.","context":"1901–1914. Символы городов мира. определите, верно ли проставлены годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Фигура на берегу","figure":{"src":"assets/golden-fleece/2008/2008_24_I-88.jpg","alt":"Бронзовая сидящая фигура на камне у воды.","width":295,"height":425},"steps":["На камне у воды сидит фигура из сказки Андерсена. Это статуя Русалочки в Копенгагене.","Её установили в 1913 году. Подпись «1903 год» неверна."]},{"question":"1905 год.","context":"1901–1914. Символы городов мира. определите, верно ли проставлены годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Лондонская башня с часами","figure":{"src":"assets/golden-fleece/2008/2008_24_I-89.jpg","alt":"Часовая башня с большим циферблатом у длинного дворца.","width":307,"height":425},"steps":["На фотографии часовая башня Вестминстерского дворца. Большой колокол внутри известен как Биг-Бен.","Часы и колокол начали работать в 1859 году. Дата 1905 не подходит."]},{"question":"1912 год.","context":"1901–1914. Символы городов мира. определите, верно ли проставлены годы их создания","choices":["Верно","Неверно","Не знаю"],"answer":1,"title":"Статуя над городом","figure":{"src":"assets/golden-fleece/2008/2008_24_I-90.jpg","alt":"Высокая статуя с распростёртыми руками на фоне неба.","width":343,"height":425},"steps":["Фигура с распростёртыми руками — статуя Христа-Искупителя на горе Корковаду в Рио-де-Жанейро.","Памятник открыли в 1931 году. В 1912-м статуя ещё не была создана."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
